export const faqContent: FaqContent = {
  title: '常见问题',
  description: '以下问答为中性默认文案，可在确认业务信息后替换为正式内容。',
  items: [
    {
      id: 'faq-1',
      question: '现在可以直接购买吗？',
      answer:
        '当前页面中的价格与链接为占位内容，用于展示页面结构；如需上线，请替换为真实购买路径与商务信息。',
    },
    {
      id: 'faq-2',
      question: '默认套餐包含哪些服务？',
      answer:
        '此处展示的是基础功能占位描述，便于开发阶段完成版式和组件联调，不代表最终交付范围。',
    },
    {
      id: 'faq-3',
      question: '这些文案可以调整吗？',
      answer:
        '可以。内容数据与展示逻辑已解耦，你可以在不修改组件结构的前提下替换标题、说明、链接和问答。',
