import React, { useState } from 'react';
import type { FaqItem } from '../content';

type FAQProps = {
  readonly title?: string;
  readonly description?: string;
  readonly items: readonly FaqItem[];
};

export function FAQ({ title, description, items }: FAQProps): React.JSX.Element {
  const [openItemId, setOpenItemId] = useState<string | null>(items[0]?.id ?? null);

  const handleToggle = (itemId: string): void => {
    setOpenItemId((current) => (current === itemId ? null : itemId));
  };

  return (
    <section aria-labelledby="faq-title" style={styles.section}>
      <div style={styles.header}>
        {title ? (
          <h2 id="faq-title" style={styles.title}>
            {title}
          </h2>
        ) : null}
        {description ? <p style={styles.description}>{description}</p> : null}
      </div>

      <div style={styles.list}>
        {items.map((item) => {
          const isOpen = openItemId === item.id;
          const buttonId = `${item.id}-button`;
          const panelId = `${item.id}-panel`;

          return (
            <div key={item.id} style={styles.item}>
              <button
                id={buttonId}
                type="button"
                aria-expanded={isOpen}
                aria-controls={panelId}
                onClick={() => handleToggle(item.id)}
                style={styles.button}
              >
                <span style={styles.question}>{item.question}</span>
                <span aria-hidden="true" style={styles.icon}>
                  {isOpen ? '−' : '+'}
                </span>
              </button>

              <div
                id={panelId}
                role="region"
                aria-labelledby={buttonId}
                hidden={!isOpen}
                style={styles.panel}
              >
                <p style={styles.answer}>{item.answer}</p>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

const styles: Record<string, React.CSSProperties> = {
  section: {
    display: 'grid',
    gap: '1.25rem',
    padding: '1.5rem',
    borderRadius: '1.25rem',
    background: '#ffffff',
    border: '1px solid rgba(15, 23, 42, 0.08)',
    boxShadow: '0 20px 45px rgba(15, 23, 42, 0.06)',
  },
  header: {
    display: 'grid',
    gap: '0.5rem',
  },
  title: {
    margin: 0,
    fontSize: 'clamp(1.5rem, 2vw, 2rem)',
    lineHeight: 1.2,
    color: '#0f172a',
  },
  description: {
    margin: 0,
    color: '#475569',
    lineHeight: 1.7,
  },
  list: {
    display: 'grid',
    gap: '0.75rem',
  },
  item: {
    borderRadius: '1rem',
    border: '1px solid rgba(148, 163, 184, 0.25)',
    overflow: 'hidden',
    background: '#f8fafc',
  },
  button: {
    width: '100%',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: '1rem',
    padding: '1rem 1.1rem',
    border: 'none',
    background: 'transparent',
    color: '#0f172a',
    cursor: 'pointer',
    textAlign: 'left',
    font: 'inherit',
  },
  question: {
    fontWeight: 600,
    lineHeight: 1.4,
  },
  icon: {
    flex: '0 0 auto',
    width: '1.75rem',
    height: '1.75rem',
    borderRadius: '999px',
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: '#e2e8f0',
    color: '#334155',
    fontSize: '1.1rem',
    lineHeight: 1,
  },
