import React, { useMemo } from 'react';
import type { PricingPlan } from '../content';

type PricingCardProps = {
  readonly plan: PricingPlan;
  readonly ctaLabel?: string;
  readonly footnote?: string;
};

type ParsedPrice = {
  readonly amount: string;
  readonly currency: string;
  readonly period: string;
};

const parsePriceLabel = (priceLabel: string): ParsedPrice => {
  const trimmedLabel = priceLabel.trim();

  const matchedPrice = trimmedLabel.match(
    /^(?<currency>[¥$€£]|RMB|CNY|USD|EUR|GBP)?\s*(?<amount>(?:\d+[\d,]*)(?:\.\d+)?|免费|待确认)(?:\s*\/(?<period>.+))?$/i,
  );

  if (matchedPrice?.groups) {
    return {
      currency: matchedPrice.groups.currency ?? '',
      amount: matchedPrice.groups.amount ?? trimmedLabel,
      period: matchedPrice.groups.period ?? '',
    };
  }

  const slashSegments = trimmedLabel.split('/');

  if (slashSegments.length > 1) {
    return {
      currency: '',
      amount: slashSegments[0]?.trim() ?? trimmedLabel,
      period: slashSegments.slice(1).join('/').trim(),
    };
  }

  return {
    currency: '',
    amount: trimmedLabel,
    period: '',
  };
};

const PricingCard = ({ plan, ctaLabel, footnote }: PricingCardProps): React.JSX.Element => {
  const parsedPrice = useMemo(() => parsePriceLabel(plan.priceLabel), [plan.priceLabel]);

  const resolvedFootnote = footnote ?? plan.priceNote;
  const resolvedCtaLabel = ctaLabel ?? plan.cta.label;

  return (
    <article
      aria-labelledby={`pricing-card-title-${plan.id}`}
      style={{
        position: 'relative',
        display: 'flex',
        flexDirection: 'column',
        gap: '1.5rem',
        padding: '2rem',
        borderRadius: '24px',
        border: plan.highlighted ? '1px solid rgba(79, 70, 229, 0.35)' : '1px solid rgba(148, 163, 184, 0.28)',
        background: plan.highlighted
          ? 'linear-gradient(180deg, rgba(238, 242, 255, 0.96) 0%, rgba(255, 255, 255, 1) 100%)'
          : 'linear-gradient(180deg, rgba(255, 255, 255, 1) 0%, rgba(248, 250, 252, 0.95) 100%)',
        boxShadow: plan.highlighted
          ? '0 24px 60px rgba(79, 70, 229, 0.14)'
          : '0 20px 48px rgba(15, 23, 42, 0.08)',
        overflow: 'hidden',
        maxWidth: '420px',
        width: '100%',
      }}
    >
      {plan.highlighted ? (
        <span
          style={{
            alignSelf: 'flex-start',
            padding: '0.4rem 0.8rem',
            borderRadius: '999px',
            backgroundColor: 'rgba(79, 70, 229, 0.12)',
            color: '#4338ca',
            fontSize: '0.8rem',
            fontWeight: 700,
            letterSpacing: '0.04em',
          }}
        >
          推荐方案
        </span>
      ) : null}

      <header style={{ display: 'flex', flexDirection: 'column', gap: '0.85rem' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
          <h3
            id={`pricing-card-title-${plan.id}`}
            style={{
              margin: 0,
              fontSize: '1.5rem',
              fontWeight: 700,
              color: '#0f172a',
              lineHeight: 1.2,
            }}
          >
            {plan.name}
          </h3>
          <p
            style={{
              margin: 0,
              color: '#475569',
              fontSize: '0.98rem',
              lineHeight: 1.7,
            }}
          >
            {plan.description}
          </p>
        </div>

        <div
          aria-label={`套餐价格：${plan.priceLabel}`}
          style={{
            display: 'flex',
            alignItems: 'flex-end',
            flexWrap: 'wrap',
            gap: '0.45rem',
          }}
        >
          {parsedPrice.currency ? (
            <span
              style={{
                fontSize: '1.25rem',
                fontWeight: 700,
                color: '#334155',
                lineHeight: 1.1,
                paddingBottom: '0.45rem',
              }}
            >
              {parsedPrice.currency}
            </span>
          ) : null}

          <span
            style={{
              fontSize: '3rem',
              fontWeight: 800,
              color: '#0f172a',
              lineHeight: 0.95,
              letterSpacing: '-0.04em',
            }}
          >
            {parsedPrice.amount}
          </span>

          {parsedPrice.period ? (
            <span
              style={{
                fontSize: '1rem',
                fontWeight: 600,
                color: '#64748b',
                lineHeight: 1.2,
                paddingBottom: '0.4rem',
              }}
            >
              / {parsedPrice.period}
            </span>
          ) : null}
        </div>
      </header>

      <ul
        style={{
          listStyle: 'none',
          margin: 0,
          padding: 0,
          display: 'grid',
          gap: '0.9rem',
        }}
      >
        {plan.features.map((feature) => (
          <li
            key={feature.id}
            style={{
              display: 'flex',
              alignItems: 'flex-start',
              gap: '0.75rem',
              color: '#334155',
              fontSize: '0.98rem',
              lineHeight: 1.6,
            }}
          >
            <span
              aria-hidden="true"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                width: '1.35rem',
                height: '1.35rem',
                borderRadius: '999px',
                backgroundColor: 'rgba(16, 185, 129, 0.14)',
                color: '#059669',
                fontSize: '0.9rem',
                fontWeight: 800,
                flexShrink: 0,
                marginTop: '0.1rem',
              }}
            >
              ✓
            </span>
            <span>{feature.text}</span>
          </li>
        ))}
      </ul>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.9rem', marginTop: '0.25rem' }}>
        <a
          href={plan.cta.href}
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            justifyContent: 'center',
            minHeight: '3.25rem',
            width: '100%',
            borderRadius: '16px',
            background: plan.highlighted
              ? 'linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%)'
              : 'linear-gradient(135deg, #0f172a 0%, #1e293b 100%)',
            color: '#ffffff',
            textDecoration: 'none',
            fontSize: '1rem',
            fontWeight: 700,
            letterSpacing: '0.01em',
            boxShadow: plan.highlighted
              ? '0 14px 28px rgba(79, 70, 229, 0.24)'
              : '0 12px 24px rgba(15, 23, 42, 0.16)',
            transition: 'transform 180ms ease, box-shadow 180ms ease, opacity 180ms ease',
          }}
        >
          {resolvedCtaLabel}
        </a>

        <div
          style={{
            padding: '0.95rem 1rem',
            borderRadius: '16px',
            backgroundColor: 'rgba(241, 245, 249, 0.9)',
            border: '1px solid rgba(148, 163, 184, 0.2)',
          }}
        >
          <p
            style={{
              margin: 0,
              fontSize: '0.88rem',
              lineHeight: 1.65,
              color: '#64748b',
            }}
          >
            {resolvedFootnote}
          </p>
        </div>
      </div>
    </article>
  );
};

export default PricingCard;

/* Global enterprise-style responsive CSS */
:root {
  --bg: #f4f7fb;
  --surface: #ffffff;
  --surface-2: #eef3f9;
  --border: #d9e2ee;
  --border-strong: #c7d4e3;
  --text: #142033;
  --text-muted: #5f6f84;
  --primary: #2457f5;
  --primary-hover: #1f49cc;
  --primary-pressed: #193ca6;
  --shadow-sm: 0 1px 2px rgba(20, 32, 51, 0.08);
  --shadow-md: 0 10px 30px rgba(20, 32, 51, 0.1);
  --shadow-lg: 0 18px 50px rgba(20, 32, 51, 0.14);
  --radius-sm: 10px;
  --radius-md: 14px;
  --radius-lg: 18px;
  --content-width: 1120px;
  --focus-ring: 0 0 0 4px rgba(36, 87, 245, 0.18);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  color-scheme: light;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  overflow-x: hidden;
  background:
    radial-gradient(circle at top, rgba(36, 87, 245, 0.08), transparent 36%),
    linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  overflow-wrap: anywhere;
}

img,
svg,
video,
canvas {
  display: block;
  max-width: 100%;
}

button,
input,
textarea,
select {
  font: inherit;
}

a {
  color: inherit;
  text-decoration: none;
}

#root {
  min-height: 100vh;
}

.page-container {
  width: min(100% - 32px, var(--content-width));
  margin: 0 auto;
  padding: 32px 0 56px;
}

.page-shell {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.page-header,
.page-section,
.card,
.faq-item {
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

.page-header,
.page-section {
  padding: 28px;
}

.page-header {
  box-shadow: var(--shadow-md);
}

.page-title {
  margin: 0 0 8px;
  font-size: clamp(1.6rem, 2.8vw, 2.4rem);
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.page-subtitle {
  margin: 0;
  max-width: 70ch;
  color: var(--text-muted);
}

.grid-layout {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 20px;
  align-items: start;
}

.stack-layout {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card {
  min-width: 0;
  padding: 24px;
  background: var(--surface);
  border-color: var(--border);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.card-title {
  margin: 0;
  font-size: 1.05rem;
  line-height: 1.3;
}

.card-description {
  margin: 6px 0 0;
  color: var(--text-muted);
}

.card-grid-4 { grid-column: span 4; }
.card-grid-6 { grid-column: span 6; }
.card-grid-8 { grid-column: span 8; }
.card-grid-12 { grid-column: 1 / -1; }

.button-group {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.button {
  appearance: none;
  max-width: 100%;
  min-height: 44px;
  padding: 10px 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: transform 160ms ease, background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease, color 160ms ease;
  white-space: normal;
  text-align: center;
  overflow-wrap: anywhere;
}

.button:hover { transform: translateY(-1px); box-shadow: var(--shadow-md); }
.button:active { transform: translateY(0); }
.button-primary { background: var(--primary); color: #fff; box-shadow: 0 10px 24px rgba(36, 87, 245, 0.22); }
.button-primary:hover { background: var(--primary-hover); }
.button-primary:active { background: var(--primary-pressed); }
.button-secondary { background: var(--surface-2); border-color: var(--border); }
.button-ghost { background: transparent; border-color: var(--border); }
.button:disabled { opacity: 0.56; cursor: not-allowed; transform: none; box-shadow: none; }

.faq-list { display: grid; gap: 12px; }
.faq-item { overflow: hidden; }

.faq-question {
  width: 100%;
  min-height: 56px;
  padding: 18px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border: 0;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  text-align: left;
}

.faq-question-title {
  margin: 0;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.faq-answer {
  padding: 0 20px 18px;
  color: var(--text-muted);
  overflow-wrap: anywhere;
}

.focusable:focus-visible,
.button:focus-visible,
.faq-question:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible,
a:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-color: var(--primary);
}

.text-truncate {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 900px) {
  .grid-layout { grid-template-columns: 1fr; }
  .card-grid-4,
  .card-grid-6,
  .card-grid-8,
  .card-grid-12 { grid-column: auto; }
  .page-header,
  .page-section,
  .card { padding: 20px; }
}

@media (max-width: 640px) {
  .page-container {
    width: min(100% - 20px, var(--content-width));
    padding: 20px 0 36px;
  }

  .page-shell,
  .stack-layout,
  .button-group,
  .faq-list { gap: 12px; }

  .button-group { flex-direction: column; align-items: stretch; }
  .button { width: 100%; }
  .faq-question { padding: 16px; align-items: flex-start; }
  .faq-answer { padding: 0 16px 16px; }
  .card-header { flex-direction: column; align-items: flex-start; }
}
